using Colony.Fields;
using Colony.Numerics;

namespace Colony.ProcGen.Tests.Pipeline;

/// <summary>
/// The test terrain of this project: a small 2D World generated by a five-stage pipeline that exercises every
/// spec 9.3 mechanism (noise terrain, region-keyed lakes, a halo-smoothed copy of the height, a world-level
/// pre-pass and a chunk-keyed placement stage). Stages are plain classes so tests can add, remove or replace them.
/// </summary>
public static class TerrainPipeline
{
    public const string HeightField = "terrain.height";
    public const string WaterField = "terrain.water";
    public const string SmoothField = "terrain.smooth";
    public const string BiomeField = "terrain.biome";
    public const string ExtraField = "terrain.extra";

    public static readonly WorldSize Size = new(64, 48, 1);

    public struct Climate : IEquatable<Climate>
    {
        public int SeaLevel;
        public int TemperatureOffset;

        public readonly bool Equals(Climate other) => SeaLevel == other.SeaLevel && TemperatureOffset == other.TemperatureOffset;

        public override readonly bool Equals(object? obj) => obj is Climate other && Equals(other);

        public override readonly int GetHashCode() => HashCode.Combine(SeaLevel, TemperatureOffset);

        public static bool operator ==(Climate left, Climate right) => left.Equals(right);

        public static bool operator !=(Climate left, Climate right) => !left.Equals(right);
    }

    /// <summary>What the Game would keep: the builders and the Field handles the stages need.</summary>
    public sealed class Composition
    {
        public required WorldBuilder Builder { get; init; }

        public required FieldsBuilder Fields { get; init; }

        public required GenerationBuilder Generation { get; init; }

        public required Field<int> Height { get; init; }

        public required Field<byte> Water { get; init; }

        public required Field<int> Smooth { get; init; }

        public required Field<byte> Biome { get; init; }

        public required Field<int> Extra { get; init; }
    }

    /// <summary>Registers Fields, the TilePos Component and the generation pipeline on a fresh builder. Stages are added by <paramref name="stages"/>.</summary>
    public static Composition Compose(Action<Composition>? stages = null, bool standardStages = true)
        => Compose(new WorldBuilder(), stages, standardStages);

    /// <summary>As <see cref="Compose(Action{Composition}?, bool)"/>, on a builder the caller owns (a harness <see cref="Testing.Scenario"/>'s).</summary>
    public static Composition Compose(WorldBuilder builder, Action<Composition>? stages = null, bool standardStages = true)
    {
        ArgumentNullException.ThrowIfNull(builder);
        builder.AddComponent<TilePos>("tile.pos");
        var fields = builder.AddFields(Size);
        var height = fields.AddField<int>(HeightField);
        var water = fields.AddField<byte>(WaterField);
        var smooth = fields.AddField<int>(SmoothField);
        var biome = fields.AddField<byte>(BiomeField);
        var extra = fields.AddField<int>(ExtraField);
        var generation = builder.AddGeneration(fields);
        generation.TilePos = builder.Component<TilePos>();
        var composition = new Composition
        {
            Builder = builder,
            Fields = fields,
            Generation = generation,
            Height = height,
            Water = water,
            Smooth = smooth,
            Biome = biome,
            Extra = extra,
        };

        if (standardStages)
        {
            generation.AddPrePass(new ClimatePrePass());
            generation.AddStage(new HeightStage(height));
            generation.AddStage(new LakeStage(water));
            generation.AddStage(new SmoothStage(height, smooth));
            generation.AddStage(new BiomeStage(height, biome));
            generation.AddStage(new TreeStage(water));
        }

        stages?.Invoke(composition);
        return composition;
    }

    public static ChunkCoord[] AllChunks()
    {
        var coords = new List<ChunkCoord>();
        for (int y = 0; y < Size.ChunksY; y++)
        {
            for (int x = 0; x < Size.ChunksX; x++)
            {
                coords.Add(new ChunkCoord(x, y, 0));
            }
        }

        return [.. coords];
    }

    /// <summary>World-level pre-pass: a climate drawn once from (seed, stage).</summary>
    public sealed class ClimatePrePass : GenerationPrePass<Climate>
    {
        public override string Name => "climate";

        public override Climate Compute(in PrePassContext context)
            => new() { SeaLevel = 90 + context.Random.Int32At(0, 0, 20), TemperatureOffset = context.Random.Int32At(1, -10, 11) };
    }

    /// <summary>Two-octave value noise over world coordinates: a pure function of the tile.</summary>
    public sealed class HeightStage : GenerationStage
    {
        private readonly Field<int> _height;

        public HeightStage(Field<int> height)
        {
            _height = height;
        }

        public override string Name => "terrain.height";

        public override IReadOnlyList<string> Writes => [HeightField];

        public override void Generate(ref ChunkGenerationContext context)
        {
            var low = context.Key.Derive(0);
            var high = context.Key.Derive(1);
            var cells = context.Write(_height);
            var origin = context.Origin;
            for (int y = 0; y < FieldChunk.Size; y++)
            {
                for (int x = 0; x < FieldChunk.Size; x++)
                {
                    var wx = Fixed32.FromInt32(origin.X + x);
                    var wy = Fixed32.FromInt32(origin.Y + y);
                    var n = Noise.Value(low, wx / Fixed32.FromInt32(24), wy / Fixed32.FromInt32(24))
                        + (Noise.Value(high, wx / Fixed32.FromInt32(6), wy / Fixed32.FromInt32(6)) * Fixed32.FromRatio(1, 3));
                    cells[FieldChunk.CellIndex(x, y, 0)] = 100 + (n * Fixed32.FromInt32(40)).ToInt32();
                }
            }
        }
    }

    /// <summary>Region-keyed lakes: spots of 32-tile regions, painted into every chunk they overlap.</summary>
    public sealed class LakeStage : GenerationStage
    {
        public const int RegionSize = 32;
        public const int MaxRadius = 10;

        private readonly Field<byte> _water;

        public LakeStage(Field<byte> water)
        {
            _water = water;
        }

        public override string Name => "feature.lakes";

        public override IReadOnlyList<string> Writes => [WaterField];

        public override IReadOnlyList<string> After => ["terrain.height"];

        public override void Generate(ref ChunkGenerationContext context)
        {
            var cells = context.Write(_water);
            var origin = context.Origin;
            Span<Spot> spots = stackalloc Spot[2];
            int rx0 = (origin.X - MaxRadius) >> 5;
            int rx1 = (origin.X + FieldChunk.Size - 1 + MaxRadius) >> 5;
            int ry0 = (origin.Y - MaxRadius) >> 5;
            int ry1 = (origin.Y + FieldChunk.Size - 1 + MaxRadius) >> 5;
            for (int ry = ry0; ry <= ry1; ry++)
            {
                for (int rx = rx0; rx <= rx1; rx++)
                {
                    int count = SpotSampler.Sample(context.Key, rx, ry, Fixed32.FromInt32(RegionSize), 0, 2, spots);
                    for (int i = 0; i < count; i++)
                    {
                        Paint(cells, origin, spots[i].Position.X.FloorToInt32(), spots[i].Position.Y.FloorToInt32(), 3 + (int)(spots[i].Hash % (MaxRadius - 2)));
                    }
                }
            }
        }

        internal static void Paint(Span<byte> cells, TilePos origin, int cx, int cy, int radius)
        {
            for (int y = 0; y < FieldChunk.Size; y++)
            {
                for (int x = 0; x < FieldChunk.Size; x++)
                {
                    int dx = origin.X + x - cx;
                    int dy = origin.Y + y - cy;
                    if ((dx * dx) + (dy * dy) <= radius * radius)
                    {
                        cells[FieldChunk.CellIndex(x, y, 0)] = 1;
                    }
                }
            }
        }
    }

    /// <summary>3x3 box blur of the height through halo reads of the neighbours' base data.</summary>
    public sealed class SmoothStage : GenerationStage
    {
        private readonly Field<int> _height;
        private readonly Field<int> _smooth;

        public SmoothStage(Field<int> height, Field<int> smooth)
        {
            _height = height;
            _smooth = smooth;
        }

        public override string Name => "terrain.smooth";

        public override IReadOnlyList<string> HaloReads => [HeightField];

        public override IReadOnlyList<string> Writes => [SmoothField];

        public override IReadOnlyList<string> After => ["terrain.height"];

        public override void Generate(ref ChunkGenerationContext context)
        {
            var halo = context.Halo(_height);
            var cells = context.Write(_smooth);
            for (int y = 0; y < FieldChunk.Size; y++)
            {
                for (int x = 0; x < FieldChunk.Size; x++)
                {
                    int sum = 0;
                    for (int dy = -1; dy <= 1; dy++)
                    {
                        for (int dx = -1; dx <= 1; dx++)
                        {
                            sum += halo[x + dx, y + dy, 0];
                        }
                    }

                    cells[FieldChunk.CellIndex(x, y, 0)] = sum / 9;
                }
            }
        }
    }

    /// <summary>Biome from height and the pre-pass climate.</summary>
    public sealed class BiomeStage : GenerationStage
    {
        private readonly Field<int> _height;
        private readonly Field<byte> _biome;

        public BiomeStage(Field<int> height, Field<byte> biome)
        {
            _height = height;
            _biome = biome;
        }

        public override string Name => "terrain.biome";

        public override IReadOnlyList<string> Reads => [HeightField];

        public override IReadOnlyList<string> Writes => [BiomeField];

        public override IReadOnlyList<string> After => ["terrain.height"];

        public override void Generate(ref ChunkGenerationContext context)
        {
            var climate = context.PrePass<Climate>();
            var height = context.Read(_height);
            var biome = context.Write(_biome);
            for (int i = 0; i < FieldChunk.CellCount; i++)
            {
                int h = height[i];
                biome[i] = h < climate.SeaLevel ? (byte)1 : h + climate.TemperatureOffset > 125 ? (byte)2 : (byte)3;
            }
        }
    }

    /// <summary>Chunk-keyed placement of trees on dry cells; Entities get ids derived from (seed, stage, chunk, index).</summary>
    public sealed class TreeStage : GenerationStage
    {
        public const int Kind = 7;

        private readonly Field<byte> _water;

        public TreeStage(Field<byte> water)
        {
            _water = water;
        }

        public override string Name => "place.trees";

        public override IReadOnlyList<string> Reads => [WaterField];

        public override IReadOnlyList<string> After => ["feature.lakes"];

        public override bool ChunkLocal => true;

        public override void Generate(ref ChunkGenerationContext context)
        {
            var water = context.Read(_water);
            int count = context.Random.Int32At(0, 2, 6);
            for (int i = 0; i < count; i++)
            {
                int cell = context.Random.Int32At(1 + (ulong)i, 0, FieldChunk.Size * FieldChunk.Size);
                if (water[cell] == 0)
                {
                    var (x, y, _) = FieldChunk.CellCoordinates(cell);
                    context.Place(new TilePos(context.Origin.X + x, context.Origin.Y + y, 0), Kind, context.Random.UInt32At(100 + (ulong)i));
                }
            }
        }
    }

    /// <summary>A stage somebody adds later: draws its own random numbers into its own Field.</summary>
    public sealed class ExtraStage : GenerationStage
    {
        private readonly Field<int> _extra;

        public ExtraStage(Field<int> extra)
        {
            _extra = extra;
        }

        public override string Name => "extra.noise";

        public override IReadOnlyList<string> Writes => [ExtraField];

        public override IReadOnlyList<string> Before => ["feature.lakes"];

        public override bool ChunkLocal => true;

        public override void Generate(ref ChunkGenerationContext context)
        {
            var cells = context.Write(_extra);
            for (int i = 0; i < cells.Length; i++)
            {
                cells[i] = (int)context.Random.UInt32At((ulong)i);
            }
        }
    }

    /// <summary>The anti-pattern the seam check exists for: lakes keyed by chunk, spilling over the chunk's edge.</summary>
    public sealed class ChunkKeyedLakeStage : GenerationStage
    {
        private readonly Field<byte> _water;

        public ChunkKeyedLakeStage(Field<byte> water)
        {
            _water = water;
        }

        public override string Name => "feature.lakes";

        public override IReadOnlyList<string> Writes => [WaterField];

        public override void Generate(ref ChunkGenerationContext context)
        {
            var cells = context.Write(_water);
            int cx = context.Origin.X + context.Random.Int32At(0, 0, FieldChunk.Size);
            int cy = context.Origin.Y + context.Random.Int32At(1, 0, FieldChunk.Size);
            LakeStage.Paint(cells, context.Origin, cx, cy, 6);
        }
    }
}
